#define SPEED 15.0

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    int time = int(iTime * SPEED) % 6;
    float posX = (uv.x + float(time)) / 6.4;

    vec4 nyanFrame = texture(iChannel0, vec2(posX, uv.y));
    fragColor = mix(vec4(0, 1, 1, 1), nyanFrame, nyanFrame.a);
}
